def slope_velocity(pos_prev_m, pos_now_m, dt_s):
    return (pos_now_m - pos_prev_m) / dt_s

def accumulate_positions(velocities_m_s, dt_s):
    pos_m = 0.0
    history = []
    for v in velocities_m_s:
        pos_m = pos_m + (v * dt_s)
        history.append(round(pos_m, 2))
    return history
